import hashlib, json

def _h(prev: bytes, row: dict) -> bytes:
    body = json.dumps(row, sort_keys=True, separators=(',', ':')).encode()
    return hashlib.sha256(prev + body).digest()

def append_audit(conn, tenant_id, principal, action, resource, outcome):
    with conn.transaction():
        # the tricky part: one writer per tenant, or two inserts fork the chain
        conn.execute('SELECT pg_advisory_xact_lock(hashtext(%s))', (tenant_id,))
        r = conn.execute('SELECT seq, row_hash FROM audit_log WHERE tenant_id=%s ORDER BY seq DESC LIMIT 1', (tenant_id,)).fetchone()
        seq, prev = (r[0] + 1, bytes(r[1])) if r else (1, hashlib.sha256(tenant_id.encode()).digest())
        row = {'tenant_id': tenant_id, 'seq': seq, 'principal': principal, 'action': action, 'resource': resource, 'outcome': outcome}
        rh = _h(prev, row)
        conn.execute('INSERT INTO audit_log(tenant_id,seq,principal,action,resource,outcome,prev_hash,row_hash) VALUES (%s,%s,%s,%s,%s,%s,%s,%s)',
                     (tenant_id, seq, principal, action, resource, outcome, prev, rh))
    return seq, rh.hex()

def verify_chain(conn, tenant_id):
    prev = hashlib.sha256(tenant_id.encode()).digest()
    for seq, p, a, res, o, rh in conn.execute('SELECT seq,principal,action,resource,outcome,row_hash FROM audit_log WHERE tenant_id=%s ORDER BY seq', (tenant_id,)):
        row = {'tenant_id': tenant_id, 'seq': seq, 'principal': p, 'action': a, 'resource': res, 'outcome': o}
        if _h(prev, row) != bytes(rh):
            return seq
        prev = bytes(rh)
    return None

