TIERS = {'plan': ['small-model', 'small-fallback'], 'context': ['small-model', 'small-fallback'], 'answer': ['large-model', 'large-fallback']}

def call(conn, client, tenant_id, team_id, task_class, messages, max_tokens, deadline_ms, idem_key):
    prior = conn.execute('SELECT 1 FROM gw_call WHERE id=%s', (idem_key,)).fetchone()
    if prior:
        raise DuplicateCall(idem_key)  # retried call must not double charge
    clean, n_red = redact(messages)
    est = estimate_cost(clean, max_tokens, TIERS[task_class][0])
    # the tricky part: check and reserve in ONE statement so two calls at the edge cannot both pass
    ok = conn.execute(
        '''UPDATE spend_meter SET used = used + %s
           WHERE tenant_id=%s AND team_id=%s AND day=current_date AND used + %s <= budget''',
        (est, tenant_id, team_id, est)).rowcount
    if ok == 0:
        raise BudgetExceeded(team_id)
    for i, model in enumerate(TIERS[task_class]):
        try:
            r = client.chat.completions.create(model=model, messages=clean, max_tokens=max_tokens, timeout=deadline_ms / 1000)
            actual = price(model, r.usage.prompt_tokens, r.usage.completion_tokens)
            conn.execute('UPDATE spend_meter SET used = used - %s + %s WHERE tenant_id=%s AND team_id=%s AND day=current_date', (est, actual, tenant_id, team_id))
            log_call(conn, idem_key, tenant_id, team_id, task_class, model, r.usage, actual, n_red, i > 0)
            return GwResponse(r.choices[0].message.content, model, actual, n_red, i > 0)
        except (TimeoutError, UpstreamError):
            continue
    conn.execute('UPDATE spend_meter SET used = used - %s WHERE tenant_id=%s AND team_id=%s AND day=current_date', (est, tenant_id, team_id))
    raise UpstreamDown()

