import httpx, json

OPA = 'http://localhost:8181/v1/data/brain/decision'

def check(req, audit):
    try:
        r = httpx.post(OPA, json={'input': req}, timeout=0.05)
        r.raise_for_status()
        res = r.json()['result']
        # the tricky part: an empty result means no rule matched, which must be deny, not allow
        decision = res.get('decision', 'deny') if res else 'deny'
        rule_ids = res.get('rule_ids', []) if res else []
        version = res.get('policy_version', 'unknown') if res else 'unknown'
        out = {'decision': decision, 'rule_ids': rule_ids, 'reason': res.get('reason', 'no_match') if res else 'no_match', 'policy_version': version}
    except (httpx.HTTPError, KeyError, ValueError):
        out = {'decision': 'deny', 'rule_ids': [], 'reason': 'engine_error', 'policy_version': 'unknown'}
    audit(req['tenant_id'], req['principal']['id'], req['action'], req['resource'], out['decision'])
    return out

